/* -------------------------------------------------------
   Function implementations
   ------------------------------------------------------- */

bool dv_slice_ok(int64_t off, int64_t len) {
    return ((((off >= 0) && (len >= 0)) && (off <= DV_TEXT_MAX)) && (len <= (DV_TEXT_MAX - off)));
}

int64_t dv_slice_len(int64_t off, int64_t len) {
    if (dv_slice_ok(off, len)) {
        return len;
    }
    return 0;
}

uint8_t dv_fold(uint8_t c) {
    if (((c >= DV_UPPER_A) && (c <= DV_UPPER_Z))) {
        return (c + DV_CASE_STEP);
    }
    return c;
}

int64_t dv_folded_bytes(uint8_t text[static 8192], int64_t off, int64_t len, uint8_t out[static 8192]) {
    int64_t n = dv_slice_len(off, len);
    int64_t i = 0;
    while ((i < n)) {
        out[i] = dv_fold(text[(off + i)]);
        i = (i + 1);
    }
    return n;
}

bool dv_contains_ci(uint8_t text[static 8192], int64_t hay_off, int64_t hay_len, int64_t needle_off, int64_t needle_len) {
    int64_t h = dv_slice_len(hay_off, hay_len);
    int64_t m = dv_slice_len(needle_off, needle_len);
    if ((m == 0)) {
        return true;
    }
    if ((m > h)) {
        return false;
    }
    uint8_t first = dv_fold(text[needle_off]);
    int64_t start = 0;
    while ((start <= (h - m))) {
        if ((dv_fold(text[(hay_off + start)]) == first)) {
            int64_t k = 1;
            bool same = true;
            while ((same && (k < m))) {
                if ((dv_fold(text[((hay_off + start) + k)]) != dv_fold(text[(needle_off + k)]))) {
                    same = false;
                }
                k = (k + 1);
            }
            if (same) {
                return true;
            }
        }
        start = (start + 1);
    }
    return false;
}

bool dv_contains_row_ci(uint8_t text[static 8192], int64_t hay_off, int64_t hay_len, int64_t row) {
    int64_t h = dv_slice_len(hay_off, hay_len);
    int64_t off = DV_ROW_OFFSETS[row];
    int64_t m = DV_ROW_LENGTHS[row];
    if ((m == 0)) {
        return true;
    }
    if ((m > h)) {
        return false;
    }
    int64_t start = 0;
    while ((start <= (h - m))) {
        int64_t k = 0;
        bool same = true;
        while ((same && (k < m))) {
            if ((dv_fold(text[((hay_off + start) + k)]) != dv_fold(DV_ROW_TEXT[(off + k)]))) {
                same = false;
            }
            k = (k + 1);
        }
        if (same) {
            return true;
        }
        start = (start + 1);
    }
    return false;
}

bool dv_equal(uint8_t text[static 8192], int64_t a_off, int64_t a_len, int64_t b_off, int64_t b_len) {
    int64_t a = dv_slice_len(a_off, a_len);
    int64_t b = dv_slice_len(b_off, b_len);
    if ((a != b)) {
        return false;
    }
    int64_t i = 0;
    while ((i < a)) {
        if ((text[(a_off + i)] != text[(b_off + i)])) {
            return false;
        }
        i = (i + 1);
    }
    return true;
}

bool dv_equal_row(uint8_t text[static 8192], int64_t off, int64_t len, int64_t row) {
    int64_t n = dv_slice_len(off, len);
    int64_t r_off = DV_ROW_OFFSETS[row];
    int64_t m = DV_ROW_LENGTHS[row];
    if ((n != m)) {
        return false;
    }
    int64_t i = 0;
    while ((i < n)) {
        if ((text[(off + i)] != DV_ROW_TEXT[(r_off + i)])) {
            return false;
        }
        i = (i + 1);
    }
    return true;
}

int64_t dv_row_bytes(int64_t row, uint8_t out[static 8192]) {
    if (((row < 0) || (row >= DV_ROW_COUNT))) {
        return 0;
    }
    int64_t off = DV_ROW_OFFSETS[row];
    int64_t n = DV_ROW_LENGTHS[row];
    int64_t i = 0;
    while ((i < n)) {
        out[i] = DV_ROW_TEXT[(off + i)];
        i = (i + 1);
    }
    return n;
}

bool dv_is_blackhole(uint8_t text[static 8192], int64_t name_off, int64_t name_len) {
    return dv_contains_row_ci(text, name_off, name_len, DV_ROW_BLACKHOLE);
}

bool dv_is_ponte_aggregate(uint8_t text[static 8192], int64_t uid_off, int64_t uid_len) {
    int64_t n = dv_slice_len(uid_off, uid_len);
    int64_t p_off = DV_ROW_OFFSETS[DV_ROW_PONTE_PREFIX];
    int64_t m = DV_ROW_LENGTHS[DV_ROW_PONTE_PREFIX];
    if ((n < m)) {
        return false;
    }
    int64_t i = 0;
    while ((i < m)) {
        if ((text[(uid_off + i)] != DV_ROW_TEXT[(p_off + i)])) {
            return false;
        }
        i = (i + 1);
    }
    return true;
}

int64_t dv_device_kind(uint8_t text[static 8192], int64_t name_off, int64_t name_len, int64_t uid_off, int64_t uid_len, uint32_t transport_type, int64_t input_channels, int64_t output_channels) {
    if (dv_is_ponte_aggregate(text, uid_off, uid_len)) {
        return DV_KIND_PONTE_AGGREGATE;
    }
    if (dv_is_blackhole(text, name_off, name_len)) {
        return DV_KIND_BLACKHOLE;
    }
    uint32_t t = transport_type;
    if ((t == DV_TRANSPORT_BUILT_IN)) {
        if ((dv_contains_row_ci(text, uid_off, uid_len, DV_ROW_HEADPHONE) || dv_contains_row_ci(text, name_off, name_len, DV_ROW_HEADPHONE))) {
            return DV_KIND_BUILT_IN_HEADPHONES;
        }
        if ((output_channels > 0)) {
            return DV_KIND_BUILT_IN_SPEAKER;
        }
        if ((input_channels > 0)) {
            return DV_KIND_BUILT_IN_MIC;
        }
        return DV_KIND_UNKNOWN;
    }
    if (((t == DV_TRANSPORT_BLUETOOTH) || (t == DV_TRANSPORT_BLUETOOTH_LE))) {
        return DV_KIND_BLUETOOTH;
    }
    if ((t == DV_TRANSPORT_USB)) {
        return DV_KIND_USB;
    }
    if (((t == DV_TRANSPORT_HDMI) || (t == DV_TRANSPORT_DISPLAYPORT))) {
        return DV_KIND_DISPLAY;
    }
    if ((t == DV_TRANSPORT_AIRPLAY)) {
        return DV_KIND_AIRPLAY;
    }
    if ((t == DV_TRANSPORT_AGGREGATE)) {
        return DV_KIND_AGGREGATE;
    }
    if ((t == DV_TRANSPORT_VIRTUAL)) {
        return DV_KIND_VIRTUAL;
    }
    if (((t == DV_TRANSPORT_CONTINUITY_WIRED) || (t == DV_TRANSPORT_CONTINUITY_WIRELESS))) {
        return DV_KIND_CONTINUITY;
    }
    if (((((t == DV_TRANSPORT_PCI) || (t == DV_TRANSPORT_FIREWIRE)) || (t == DV_TRANSPORT_THUNDERBOLT)) || (t == DV_TRANSPORT_AVB))) {
        return DV_KIND_OTHER_WIRED;
    }
    return DV_KIND_UNKNOWN;
}

int64_t dv_echo_risk(int64_t kind) {
    if ((((kind == DV_KIND_BUILT_IN_SPEAKER) || (kind == DV_KIND_DISPLAY)) || (kind == DV_KIND_AIRPLAY))) {
        return DV_ECHO_SPEAKER;
    }
    if (((((kind == DV_KIND_BLUETOOTH) || (kind == DV_KIND_USB)) || (kind == DV_KIND_OTHER_WIRED)) || (kind == DV_KIND_UNKNOWN))) {
        return DV_ECHO_MAYBE;
    }
    return DV_ECHO_NONE;
}

bool dv_is_excluded_for_monitoring(int64_t kind) {
    return ((kind == DV_KIND_BLACKHOLE) || (kind == DV_KIND_PONTE_AGGREGATE));
}

int64_t dv_list_count(int64_t count) {
    if ((count < 0)) {
        return 0;
    }
    if ((count > DV_LIST_MAX)) {
        return DV_LIST_MAX;
    }
    return count;
}

int64_t dv_pick_blackhole_index(uint8_t text[static 8192], uint32_t name_offsets[static 256], uint32_t name_lengths[static 256], int64_t output_channels[static 256], int64_t count) {
    int64_t n = dv_list_count(count);
    int64_t first = -1;
    int64_t i = 0;
    while ((i < n)) {
        if ((dv_is_blackhole(text, name_offsets[i], name_lengths[i]) && (output_channels[i] > 0))) {
            if (dv_contains_row_ci(text, name_offsets[i], name_lengths[i], DV_ROW_TWO_CH)) {
                return i;
            }
            if ((first < 0)) {
                first = i;
            }
        }
        i = (i + 1);
    }
    return first;
}

bool dv_usable(int64_t kind, int64_t channels) {
    return ((channels > 0) && (dv_is_excluded_for_monitoring(kind) == false));
}

int64_t dv_pick_mic_index(int64_t kinds[static 256], int64_t input_channels[static 256], int64_t count, int64_t default_index) {
    int64_t n = dv_list_count(count);
    if (((default_index >= 0) && (default_index < n))) {
        if (dv_usable(kinds[default_index], input_channels[default_index])) {
            return default_index;
        }
    }
    int64_t i = 0;
    while ((i < n)) {
        if ((dv_usable(kinds[i], input_channels[i]) && (kinds[i] == DV_KIND_BUILT_IN_MIC))) {
            return i;
        }
        i = (i + 1);
    }
    i = 0;
    while ((i < n)) {
        if (dv_usable(kinds[i], input_channels[i])) {
            return i;
        }
        i = (i + 1);
    }
    return -1;
}

int64_t dv_pick_listen_output_index(int64_t kinds[static 256], int64_t output_channels[static 256], int64_t count, int64_t default_index) {
    int64_t n = dv_list_count(count);
    if (((default_index >= 0) && (default_index < n))) {
        if (dv_usable(kinds[default_index], output_channels[default_index])) {
            return default_index;
        }
    }
    int64_t p = 0;
    while ((p < 4)) {
        int64_t i = 0;
        while ((i < n)) {
            if ((dv_usable(kinds[i], output_channels[i]) && (kinds[i] == DV_LISTEN_PRIORITY[p]))) {
                return i;
            }
            i = (i + 1);
        }
        p = (p + 1);
    }
    int64_t j = 0;
    while ((j < n)) {
        if (dv_usable(kinds[j], output_channels[j])) {
            return j;
        }
        j = (j + 1);
    }
    return -1;
}

int64_t dv_match_device_index(uint8_t text[static 8192], int64_t query_off, int64_t query_len, uint32_t name_offsets[static 256], uint32_t name_lengths[static 256], uint32_t uid_offsets[static 256], uint32_t uid_lengths[static 256], int64_t count) {
    int64_t n = dv_list_count(count);
    int64_t i = 0;
    while ((i < n)) {
        if (dv_equal(text, uid_offsets[i], uid_lengths[i], query_off, query_len)) {
            return i;
        }
        i = (i + 1);
    }
    i = 0;
    while ((i < n)) {
        if (dv_equal(text, name_offsets[i], name_lengths[i], query_off, query_len)) {
            return i;
        }
        i = (i + 1);
    }
    i = 0;
    while ((i < n)) {
        if (dv_contains_ci(text, name_offsets[i], name_lengths[i], query_off, query_len)) {
            return i;
        }
        i = (i + 1);
    }
    return -1;
}

int64_t dv_known_call_app_index(uint8_t text[static 8192], int64_t id_off, int64_t id_len) {
    int64_t i = 0;
    while ((i < DV_CALL_APPS)) {
        if (dv_equal_row(text, id_off, id_len, (DV_ROW_FIRST_APP + i))) {
            return i;
        }
        i = (i + 1);
    }
    return -1;
}

bool dv_is_known_call_app(uint8_t text[static 8192], int64_t id_off, int64_t id_len) {
    return (dv_known_call_app_index(text, id_off, id_len) >= 0);
}

int64_t dv_call_app_bundle_id(int64_t index, uint8_t out[static 8192]) {
    if (((index < 0) || (index >= DV_CALL_APPS))) {
        return 0;
    }
    return dv_row_bytes((DV_ROW_FIRST_APP + index), out);
}

int64_t dv_call_app_label(int64_t index, uint8_t out[static 8192]) {
    if (((index < 0) || (index >= DV_CALL_APPS))) {
        return 0;
    }
    return dv_row_bytes((DV_ROW_FIRST_LABEL + index), out);
}

bool dv_is_companion_process(uint8_t text[static 8192], int64_t process_off, int64_t process_len, int64_t target_off, int64_t target_len) {
    int64_t i = 0;
    while ((i < DV_COMPANIONS)) {
        if ((dv_equal_row(text, target_off, target_len, (DV_ROW_FIRST_COMPANION_TARGET + i)) && dv_equal_row(text, process_off, process_len, (DV_ROW_FIRST_COMPANION_PROCESS + i)))) {
            return true;
        }
        i = (i + 1);
    }
    return false;
}

bool dv_is_tap_target_process(uint8_t text[static 8192], int64_t process_off, int64_t process_len, int64_t owner_off, int64_t owner_len, int64_t target_off, int64_t target_len, int32_t pid, int32_t self_pid) {
    if ((pid == self_pid)) {
        return false;
    }
    if (dv_equal(text, owner_off, owner_len, target_off, target_len)) {
        return true;
    }
    if (((dv_slice_len(process_off, process_len) > 0) && dv_equal(text, process_off, process_len, target_off, target_len))) {
        return true;
    }
    return dv_is_companion_process(text, process_off, process_len, target_off, target_len);
}

int64_t dv_parent_app_index(uint8_t text[static 8192], int64_t helper_off, int64_t helper_len, uint32_t app_offsets[static 256], uint32_t app_lengths[static 256], int64_t count) {
    int64_t n = dv_list_count(count);
    int64_t h = dv_slice_len(helper_off, helper_len);
    int64_t best = -1;
    int64_t best_length = -1;
    int64_t i = 0;
    while ((i < n)) {
        int64_t a_off = app_offsets[i];
        int64_t a = dv_slice_len(a_off, app_lengths[i]);
        if ((((a > 0) && ((a + 1) <= h)) && ((a + 1) > best_length))) {
            bool same = (text[(helper_off + a)] == DV_DOT);
            int64_t k = 0;
            while ((same && (k < a))) {
                if ((text[(helper_off + k)] != text[(a_off + k)])) {
                    same = false;
                }
                k = (k + 1);
            }
            if (same) {
                best = i;
                best_length = (a + 1);
            }
        }
        i = (i + 1);
    }
    return best;
}

int64_t dv_outermost_app_path_length(uint8_t text[static 8192], int64_t path_off, int64_t path_len) {
    int64_t n = dv_slice_len(path_off, path_len);
    int64_t s_off = DV_ROW_OFFSETS[DV_ROW_APP_SUFFIX];
    int64_t s = DV_ROW_LENGTHS[DV_ROW_APP_SUFFIX];
    int64_t i = 0;
    while (((i + s) <= n)) {
        bool same = true;
        int64_t k = 0;
        while ((same && (k < s))) {
            if ((text[((path_off + i) + k)] != DV_ROW_TEXT[(s_off + k)])) {
                same = false;
            }
            k = (k + 1);
        }
        if (same) {
            int64_t end = (i + s);
            int64_t component_start = 0;
            int64_t j = (i - 1);
            while ((j >= 0)) {
                if ((text[(path_off + j)] == DV_SLASH)) {
                    component_start = (j + 1);
                    j = -1;
                } else {
                    j = (j - 1);
                }
            }
            if ((((end == n) || (text[(path_off + end)] == DV_SLASH)) && (i > component_start))) {
                return end;
            }
        }
        i = (i + 1);
    }
    return -1;
}

int64_t dv_owner_source(bool self_is_regular_app, bool has_app_bundle_path, bool has_responsible_app, bool has_regular_parent_app, bool has_prefix_parent) {
    if (self_is_regular_app) {
        return DV_OWNER_SELF;
    }
    if (has_app_bundle_path) {
        return DV_OWNER_APP_BUNDLE_PATH;
    }
    if (has_responsible_app) {
        return DV_OWNER_RESPONSIBLE;
    }
    if (has_regular_parent_app) {
        return DV_OWNER_PARENT;
    }
    if (has_prefix_parent) {
        return DV_OWNER_BUNDLE_PREFIX;
    }
    return DV_OWNER_FALLBACK;
}

bool dv_is_self_process(int32_t pid, int32_t owner_pid, int32_t self_pid) {
    return ((pid == self_pid) || (owner_pid == self_pid));
}

bool dv_should_list_app(bool is_regular_app, bool is_playing, bool is_known_call_app) {
    return ((is_regular_app || is_playing) || is_known_call_app);
}

int64_t dv_app_rank(bool is_known_call_app, bool is_playing) {
    if ((is_known_call_app && is_playing)) {
        return DV_RANK_PLAYING_CALL_APP;
    }
    if (is_playing) {
        return DV_RANK_PLAYING;
    }
    if (is_known_call_app) {
        return DV_RANK_IDLE_CALL_APP;
    }
    return DV_RANK_OTHER;
}

bool dv_app_before(int64_t ranks[static 256], uint8_t text[static 8192], uint32_t name_offsets[static 256], uint32_t name_lengths[static 256], int64_t a, int64_t b) {
    if ((ranks[a] != ranks[b])) {
        return (ranks[a] < ranks[b]);
    }
    int64_t a_off = name_offsets[a];
    int64_t b_off = name_offsets[b];
    int64_t a_len = dv_slice_len(a_off, name_lengths[a]);
    int64_t b_len = dv_slice_len(b_off, name_lengths[b]);
    int64_t i = 0;
    while (((i < a_len) && (i < b_len))) {
        uint8_t x = dv_fold(text[(a_off + i)]);
        uint8_t y = dv_fold(text[(b_off + i)]);
        if ((x != y)) {
            return (x < y);
        }
        i = (i + 1);
    }
    if ((a_len != b_len)) {
        return (a_len < b_len);
    }
    return (a < b);
}

int64_t dv_app_sort_order(int64_t ranks[static 256], uint8_t text[static 8192], uint32_t name_offsets[static 256], uint32_t name_lengths[static 256], int64_t count, int64_t order[static 256]) {
    int64_t n = dv_list_count(count);
    int64_t i = 0;
    while ((i < n)) {
        order[i] = i;
        i = (i + 1);
    }
    i = 1;
    while ((i < n)) {
        int64_t item = order[i];
        int64_t j = (i - 1);
        bool moving = true;
        while ((moving && (j >= 0))) {
            if (dv_app_before(ranks, text, name_offsets, name_lengths, item, order[j])) {
                order[(j + 1)] = order[j];
                j = (j - 1);
            } else {
                moving = false;
            }
        }
        order[(j + 1)] = item;
        i = (i + 1);
    }
    return n;
}

bool dv_is_regular_app(bool regular_policy, bool has_bundle_id) {
    return (regular_policy && has_bundle_id);
}

bool dv_process_pid_valid(int32_t pid) {
    return (pid > 0);
}

bool dv_responsible_usable(int32_t responsible_pid, int32_t pid) {
    return ((responsible_pid != pid) && (responsible_pid > DV_LAUNCHD_PID));
}

bool dv_parent_continues(int32_t parent_pid, int32_t current) {
    return ((parent_pid > DV_LAUNCHD_PID) && (parent_pid != current));
}

int64_t dv_owner_id_source(bool has_hal_id, bool has_app_id) {
    if (has_hal_id) {
        return DV_ID_HAL;
    }
    if (has_app_id) {
        return DV_ID_APP;
    }
    return DV_ID_PID;
}

int64_t dv_owner_name_source(bool has_app_name, bool has_path) {
    if (has_app_name) {
        return DV_NAME_APP;
    }
    if (has_path) {
        return DV_NAME_PATH;
    }
    return DV_NAME_ID;
}

int64_t dv_bundle_name_source(bool has_running_name, bool has_display_name, bool has_bundle_name) {
    if (has_running_name) {
        return DV_BUNDLE_NAME_RUNNING;
    }
    if (has_display_name) {
        return DV_BUNDLE_NAME_DISPLAY;
    }
    if (has_bundle_name) {
        return DV_BUNDLE_NAME_BUNDLE;
    }
    return DV_BUNDLE_NAME_FILE;
}

bool dv_path_owner_regular(bool has_running, bool running_regular, bool has_self, bool self_regular) {
    if (has_running) {
        return running_regular;
    }
    if (has_self) {
        return self_regular;
    }
    return false;
}

bool dv_app_playing(bool already_playing, bool process_playing) {
    return (already_playing || process_playing);
}

bool dv_prefers_owner(bool candidate_regular, bool current_regular) {
    return (candidate_regular && (current_regular == false));
}

bool dv_needs_headphones(int64_t kind) {
    return (dv_echo_risk(kind) == DV_ECHO_SPEAKER);
}

bool dv_is_ponte_id(uint8_t text[static 8192], int64_t id_off, int64_t id_len) {
    return dv_equal_row(text, id_off, id_len, DV_ROW_PONTE_ID);
}

int64_t dv_reader_role(uint8_t text[static 8192], int64_t owner_off, int64_t owner_len, int64_t target_off, int64_t target_len, bool has_target, int32_t pid, int32_t self_pid) {
    if (((pid == self_pid) || dv_is_ponte_id(text, owner_off, owner_len))) {
        return DV_READER_PONTE;
    }
    if (has_target) {
        if ((dv_equal(text, owner_off, owner_len, target_off, target_len) || dv_is_companion_process(text, owner_off, owner_len, target_off, target_len))) {
            return DV_READER_CALL;
        }
        return DV_READER_OTHER;
    }
    if (dv_is_known_call_app(text, owner_off, owner_len)) {
        return DV_READER_CALL;
    }
    return DV_READER_OTHER;
}

bool dv_is_real_mic_kind(int64_t kind) {
    return ((((kind != DV_KIND_BLACKHOLE) && (kind != DV_KIND_PONTE_AGGREGATE)) && (kind != DV_KIND_VIRTUAL)) && (kind != DV_KIND_AGGREGATE));
}

int64_t dv_reader_use(int64_t role, int64_t kind, bool running_input) {
    if (((running_input == false) || (role == DV_READER_PONTE))) {
        return DV_USE_NONE;
    }
    if ((kind == DV_KIND_BLACKHOLE)) {
        if ((role == DV_READER_CALL)) {
            return DV_USE_CALL_BLACKHOLE;
        }
        return DV_USE_OTHER_BLACKHOLE;
    }
    if (((role == DV_READER_CALL) && dv_is_real_mic_kind(kind))) {
        return DV_USE_CALL_REAL_MIC;
    }
    return DV_USE_NONE;
}

int64_t dv_listen_status(int64_t uses[static 256], int64_t count, bool listed, bool blackhole_present) {
    if ((blackhole_present == false)) {
        return DV_LISTEN_NO_BLACKHOLE;
    }
    if ((listed == false)) {
        return DV_LISTEN_UNKNOWN;
    }
    int64_t n = dv_list_count(count);
    bool call_blackhole = false;
    bool other_blackhole = false;
    bool call_mic = false;
    int64_t i = 0;
    while ((i < n)) {
        if ((uses[i] == DV_USE_CALL_BLACKHOLE)) {
            call_blackhole = true;
        }
        if ((uses[i] == DV_USE_OTHER_BLACKHOLE)) {
            other_blackhole = true;
        }
        if ((uses[i] == DV_USE_CALL_REAL_MIC)) {
            call_mic = true;
        }
        i = (i + 1);
    }
    if (call_mic) {
        if (call_blackhole) {
            return DV_LISTEN_BOTH;
        }
        return DV_LISTEN_REAL_MIC;
    }
    if ((call_blackhole || other_blackhole)) {
        return DV_LISTEN_OK;
    }
    return DV_LISTEN_NOBODY;
}

int64_t dv_first_use(int64_t uses[static 256], int64_t count, int64_t wanted) {
    int64_t n = dv_list_count(count);
    int64_t i = 0;
    while ((i < n)) {
        if ((uses[i] == wanted)) {
            return i;
        }
        i = (i + 1);
    }
    return -1;
}

int64_t dv_listen_index(int64_t uses[static 256], int64_t count) {
    int64_t i = dv_first_use(uses, count, DV_USE_CALL_REAL_MIC);
    if ((i >= 0)) {
        return i;
    }
    i = dv_first_use(uses, count, DV_USE_CALL_BLACKHOLE);
    if ((i >= 0)) {
        return i;
    }
    return dv_first_use(uses, count, DV_USE_OTHER_BLACKHOLE);
}

bool dv_is_headphones_like(int64_t kind) {
    return (((kind == DV_KIND_BUILT_IN_HEADPHONES) || (kind == DV_KIND_BLUETOOTH)) || (kind == DV_KIND_USB));
}

bool dv_auto_mic_allowed(int64_t kind, int64_t channels) {
    return (((channels > 0) && (dv_is_excluded_for_monitoring(kind) == false)) && (kind != DV_KIND_CONTINUITY));
}

bool dv_headset_mic_matches(uint8_t text[static 8192], uint32_t name_offsets[static 256], uint32_t name_lengths[static 256], int64_t kinds[static 256], int64_t i, int64_t output) {
    if ((i == output)) {
        return true;
    }
    if ((kinds[i] != kinds[output])) {
        return false;
    }
    if ((kinds[i] == DV_KIND_BUILT_IN_HEADPHONES)) {
        return true;
    }
    return dv_equal(text, name_offsets[i], name_lengths[i], name_offsets[output], name_lengths[output]);
}

int64_t dv_pick_auto_mic_index(uint8_t text[static 8192], uint32_t name_offsets[static 256], uint32_t name_lengths[static 256], int64_t kinds[static 256], int64_t input_channels[static 256], int64_t count, int64_t output_index) {
    int64_t n = dv_list_count(count);
    int64_t i = 0;
    if (((output_index >= 0) && (output_index < n))) {
        if (dv_is_headphones_like(kinds[output_index])) {
            while ((i < n)) {
                if ((dv_auto_mic_allowed(kinds[i], input_channels[i]) && dv_headset_mic_matches(text, name_offsets, name_lengths, kinds, i, output_index))) {
                    return i;
                }
                i = (i + 1);
            }
        }
    }
    i = 0;
    while ((i < n)) {
        if ((dv_auto_mic_allowed(kinds[i], input_channels[i]) && (kinds[i] == DV_KIND_BUILT_IN_MIC))) {
            return i;
        }
        i = (i + 1);
    }
    i = 0;
    while ((i < n)) {
        if ((dv_auto_mic_allowed(kinds[i], input_channels[i]) && dv_is_real_mic_kind(kinds[i]))) {
            return i;
        }
        i = (i + 1);
    }
    return -1;
}

int64_t dv_fixture(int64_t index, uint8_t text[static 8192], int64_t at) {
    if ((((index < 0) || (index >= DV_FX_COUNT)) || (at < 0))) {
        return 0;
    }
    int64_t off = DV_FX_OFFSETS[index];
    int64_t len = DV_FX_LENGTHS[index];
    int64_t k = 0;
    while (((k < len) && ((at + k) < DV_TEXT_MAX))) {
        text[(at + k)] = DV_FX_TEXT[(off + k)];
        k = (k + 1);
    }
    return k;
}

int64_t dv_fixture_push(int64_t index, uint8_t text[static 8192], int64_t at, uint32_t offsets[static 256], uint32_t lengths[static 256], int64_t slot) {
    int64_t n = dv_fixture(index, text, at);
    offsets[slot] = ((uint32_t)(at));
    lengths[slot] = ((uint32_t)(n));
    return (at + n);
}

